/* Exploratory title-based matching, not an aptitude test or academic/admission audit. */
var CatalogPathfinder=(()=>{
 const topics={engineering:/engineer|robot|manufactur|construction|aeronaut|aerospace|mechatron/i,computing:/computer|computing|software|informatics|cyber|information technology|data science|web development/i,quantitative:/math|statistic|actuar|data analytics|econometric|physics|chemistry/i,life:/biolog|biochem|genetic|microbi|neurosc|zoolog|botan|molecular/i,health:/nurs|health|medic|dental|nutrition|pharma|therapy|diagnostic|clinical/i,environment:/environment|ocean|marine|earth|geolog|climate|forest|ecolog|sustain|wildlife|agricult/i,society:/psycholog|sociolog|social|politic|public policy|justice|anthropol|ethnic|gender|global studies|international studies|community/i,business:/business|account|financ|market|entrepreneur|management|economics|supply chain|hospitality|real estate/i,arts:/design|art(?:s|istic)?\b|music|drama|theat|dance|film|animation|architecture|ceramic/i,communication:/communicat|journal|media|writing|rhetoric|linguistic|speech|literacy/i,humanities:/history|histor|philosoph|literature|english|classics|religio|humanit|language|spanish|french|japanese|chinese|korean|german|russian|arabic|italian|scandinavian|indigenous/i,education:/educat|teach|learning|early childhood|child development/i};
 const vectors={engineering:{build:3,logic:2,research:1},computing:{logic:3,build:2,create:1},quantitative:{logic:3,research:3},life:{research:3,people:1,logic:1},health:{people:3,research:2,build:1},environment:{research:3,build:1,people:1},society:{people:3,research:2,lead:1},business:{lead:3,logic:1,people:1},arts:{create:3,build:1},communication:{create:2,people:2,lead:1},humanities:{create:2,people:2,research:1},education:{people:3,create:1,lead:1}};
 const defaults={build:['engineering'],logic:['computing','quantitative'],people:['society','education','health'],create:['arts','humanities','communication'],research:['life','environment','quantitative'],lead:['business','society']};const cache=new Map();
 const hash=s=>{let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return(h>>>0)/4294967296};
 function profile(p){if(cache.has(p.id))return cache.get(p.id);const text=[p.title,p.parentMajor,p.department].filter(Boolean).join(' ').replace(/Bachelor(?:s|’s|'s)?(?: of)? (?:Arts|Science|Fine Arts|Music|Applied Science)|Associate(?: in| of)? (?:Arts|Science|Applied Science)/gi,''),domains=Object.entries(topics).filter(([,r])=>r.test(text)).map(([k])=>k),traits={};for(const d of domains)for(const[k,v]of Object.entries(vectors[d]))traits[k]=(traits[k]||0)+v;const out={domains:domains.length?domains:['interdisciplinary'],traits:Object.keys(traits).length?traits:{research:1,people:1,create:1,logic:1,lead:1,build:1}};cache.set(p.id,out);return out}
 function signals(answers,questions=[]){const traits={},domains={};answers.forEach((tag,i)=>{if(!defaults[tag])return;traits[tag]=(traits[tag]||0)+1;for(const d of defaults[tag])domains[d]=(domains[d]||0)+.25;const q=questions[i],choice=q?.choices?.[q.tags?.indexOf(tag)]||'';for(const[d,re]of Object.entries(topics))if(re.test(choice))domains[d]=(domains[d]||0)+2;});return{traits,domains}}
 function cosine(a,b){let dot=0,aa=0,bb=0;for(const v of Object.values(a))aa+=v*v;for(const v of Object.values(b))bb+=v*v;for(const k of Object.keys(a))dot+=(a[k]||0)*(b[k]||0);return aa&&bb?dot/Math.sqrt(aa*bb):0}
 function rank(answers,programs,questions=[],options={}){const signal=signals(answers,questions),seed=answers.join('|'),schoolPriority={'UW Seattle':3,'UW Bothell':2,'Bellevue College':1};return programs.filter(p=>p.available!==false).map(p=>{const model=profile(p),domainVector=Object.fromEntries(model.domains.map(k=>[k,1])),fit=.52*cosine(signal.traits,model.traits)+.48*cosine(signal.domains,domainVector),tie=hash(seed+'|'+p.parentMajor+'|'+p.title)*.006,school=(schoolPriority[p.institution]||0)*.0001,target=(options.school&&p.institution===options.school)?.02:0,broad=/^(?:Associate|Science,? Track|Direct Transfer|General Studies|Transfer Degree)/i.test(p.title)?.09:0;return{...p,name:p.title,programId:p.id,key:'catalog:'+p.id,family:(p.parentMajor||p.title).toLowerCase(),tags:Object.entries(model.traits).sort((a,b)=>b[1]-a[1]).slice(0,2).map(([k])=>k),domains:model.domains,weight:fit+tie+school+target-broad,match:fit,reason:model.domains.filter(k=>signal.domains[k]).slice(0,3)}}).sort((a,b)=>b.weight-a.weight||a.id.localeCompare(b.id))}
 function shortlist(ranked,count=3){const picked=[],families=new Set();for(const p of ranked){if(families.has(p.family))continue;picked.push(p);families.add(p.family);if(picked.length===count)break}return picked}
 return{rank,shortlist,profile,signals,topics:Object.keys(topics)};
})();if(typeof module!=='undefined')module.exports=CatalogPathfinder;
